package com.mukasanches.zapptv.platform

import android.content.Context
import androidx.work.CoroutineWorker
import androidx.work.ExistingPeriodicWorkPolicy
import androidx.work.NetworkType
import androidx.work.PeriodicWorkRequestBuilder
import androidx.work.Constraints
import androidx.work.WorkManager
import androidx.work.WorkerParameters
import com.mukasanches.zapptv.data.IptvRepository
import java.util.concurrent.TimeUnit

class CatalogRefreshWorker(
    appContext: Context,
    params: WorkerParameters
) : CoroutineWorker(appContext, params) {
    override suspend fun doWork(): Result = runCatching {
        IptvRepository(applicationContext).refresh(force = true)
        Result.success()
    }.getOrElse { Result.retry() }

    companion object {
        private const val UNIQUE_WORK = "sanchestv-catalog-refresh"

        fun schedule(context: Context) {
            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.CONNECTED)
                .build()
            val request = PeriodicWorkRequestBuilder<CatalogRefreshWorker>(3, TimeUnit.HOURS)
                .setConstraints(constraints)
                .build()
            WorkManager.getInstance(context).enqueueUniquePeriodicWork(
                UNIQUE_WORK,
                ExistingPeriodicWorkPolicy.UPDATE,
                request
            )
        }
    }
}

package com.mukasanches.zapptv.platform

import android.app.DownloadManager
import android.content.Context
import android.net.Uri
import android.os.Environment
import android.webkit.MimeTypeMap
import com.mukasanches.zapptv.model.Channel
import org.json.JSONArray
import org.json.JSONObject

data class FeatureDownload(
    val id: Long,
    val title: String,
    val url: String,
    val status: Int,
    val progress: Int,
    val reason: Int
)

class FeatureDownloads(private val context: Context) {
    private val manager = context.getSystemService(Context.DOWNLOAD_SERVICE) as DownloadManager
    private val prefs = context.getSharedPreferences("sanchestv_downloads", Context.MODE_PRIVATE)

    fun enqueue(channel: Channel): Result<Long> {
        val url = channel.playbackUris().firstOrNull()
            ?: return Result.failure(IllegalArgumentException("Canal sem mídia baixável"))

        val normalized = url.substringBefore('?').lowercase()
        if (normalized.endsWith(".m3u8") || normalized.endsWith(".mpd")) {
            return Result.failure(
                IllegalArgumentException("Transmissões ao vivo HLS/DASH não são salvas como arquivo único")
            )
        }

        return runCatching {
            val uri = Uri.parse(url)
            val extension = MimeTypeMap.getFileExtensionFromUrl(url).take(6)
            val safeTitle = channel.name
                .replace(Regex("[^A-Za-z0-9À-ÿ._ -]"), "")
                .trim()
                .take(56)
                .ifBlank { "SANCHESTV" }
            val fileName = if (extension.isBlank()) {
                "${safeTitle}.media"
            } else {
                "${safeTitle}.${extension}"
            }
            val mime = extension.takeIf { it.isNotBlank() }
                ?.let { MimeTypeMap.getSingleton().getMimeTypeFromExtension(it.lowercase()) }

            val request = DownloadManager.Request(uri)
                .setTitle(channel.name)
                .setDescription("SANCHESTV")
                .setAllowedOverMetered(true)
                .setAllowedOverRoaming(false)
                .setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED)
                .setDestinationInExternalFilesDir(context, Environment.DIRECTORY_MOVIES, fileName)

            if (!mime.isNullOrBlank()) request.setMimeType(mime)

            val id = manager.enqueue(request)
            remember(id, channel.name, url)
            id
        }
    }

    fun list(): List<FeatureDownload> {
        val saved = records()
        if (saved.isEmpty()) return emptyList()

        return saved.mapNotNull { record ->
            val id = record.optLong("id", -1L)
            if (id <= 0L) return@mapNotNull null

            manager.query(DownloadManager.Query().setFilterById(id)).use { cursor ->
                if (!cursor.moveToFirst()) return@use null

                val status = cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS))
                val reason = cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_REASON))
                val downloaded = cursor.getLong(
                    cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR)
                )
                val total = cursor.getLong(
                    cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES)
                )
                val progress = if (total > 0L) {
                    ((downloaded * 100L) / total).toInt().coerceIn(0, 100)
                } else if (status == DownloadManager.STATUS_SUCCESSFUL) {
                    100
                } else {
                    0
                }

                FeatureDownload(
                    id = id,
                    title = record.optString("title", "Mídia"),
                    url = record.optString("url", ""),
                    status = status,
                    progress = progress,
                    reason = reason
                )
            }
        }
    }

    fun remove(id: Long) {
        manager.remove(id)
        save(records().filterNot { it.optLong("id") == id })
    }

    private fun remember(id: Long, title: String, url: String) {
        val updated = records()
            .filterNot { it.optLong("id") == id }
            .toMutableList()
        updated.add(
            0,
            JSONObject()
                .put("id", id)
                .put("title", title.take(80))
                .put("url", url)
        )
        save(updated.take(MAX_RECORDS))
    }

    private fun records(): List<JSONObject> {
        val raw = prefs.getString(KEY_RECORDS, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (index in 0 until array.length()) {
                    array.optJSONObject(index)?.let(::add)
                }
            }
        }.getOrDefault(emptyList())
    }

    private fun save(records: List<JSONObject>) {
        val array = JSONArray()
        records.forEach(array::put)
        prefs.edit().putString(KEY_RECORDS, array.toString()).apply()
    }

    companion object {
        private const val KEY_RECORDS = "records"
        private const val MAX_RECORDS = 100
    }
}

package com.mukasanches.zapptv.platform

import android.content.Context
import org.json.JSONArray

data class PlaybackPreferences(
    val subtitlesEnabled: Boolean = true,
    val preferredAudioLanguage: String = "pt-BR",
    val preferredSubtitleLanguage: String = "pt-BR",
    val previewMuted: Boolean = true,
    val notificationsEnabled: Boolean = true
)

class FeaturePreferences(context: Context) {
    private val prefs = context.getSharedPreferences("sanchestv_features", Context.MODE_PRIVATE)

    fun playback(): PlaybackPreferences = PlaybackPreferences(
        subtitlesEnabled = prefs.getBoolean(KEY_SUBTITLES, true),
        preferredAudioLanguage = prefs.getString(KEY_AUDIO_LANGUAGE, "pt-BR") ?: "pt-BR",
        preferredSubtitleLanguage = prefs.getString(KEY_SUBTITLE_LANGUAGE, "pt-BR") ?: "pt-BR",
        previewMuted = prefs.getBoolean(KEY_PREVIEW_MUTED, true),
        notificationsEnabled = prefs.getBoolean(KEY_NOTIFICATIONS, true)
    )

    fun savePlayback(value: PlaybackPreferences) {
        prefs.edit()
            .putBoolean(KEY_SUBTITLES, value.subtitlesEnabled)
            .putString(KEY_AUDIO_LANGUAGE, value.preferredAudioLanguage)
            .putString(KEY_SUBTITLE_LANGUAGE, value.preferredSubtitleLanguage)
            .putBoolean(KEY_PREVIEW_MUTED, value.previewMuted)
            .putBoolean(KEY_NOTIFICATIONS, value.notificationsEnabled)
            .apply()
    }

    fun searchHistory(limit: Int = 20): List<String> {
        val raw = prefs.getString(KEY_SEARCH_HISTORY, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (index in 0 until array.length()) {
                    val value = array.optString(index).trim()
                    if (value.isNotBlank()) add(value)
                    if (size >= limit) break
                }
            }
        }.getOrDefault(emptyList())
    }

    fun recordSearch(query: String) {
        val clean = query.trim().replace(Regex("\\s+"), " ").take(80)
        if (clean.length < 2) return

        val updated = searchHistory(40)
            .filterNot { it.equals(clean, ignoreCase = true) }
            .toMutableList()
            .apply { add(0, clean) }
            .take(40)

        val json = JSONArray()
        updated.forEach(json::put)
        prefs.edit().putString(KEY_SEARCH_HISTORY, json.toString()).apply()
    }

    fun clearSearchHistory() {
        prefs.edit().remove(KEY_SEARCH_HISTORY).apply()
    }

    companion object {
        private const val KEY_SUBTITLES = "subtitles_enabled"
        private const val KEY_AUDIO_LANGUAGE = "audio_language"
        private const val KEY_SUBTITLE_LANGUAGE = "subtitle_language"
        private const val KEY_PREVIEW_MUTED = "preview_muted"
        private const val KEY_NOTIFICATIONS = "notifications_enabled"
        private const val KEY_SEARCH_HISTORY = "search_history"
    }
}

package com.mukasanches.zapptv.platform

import android.annotation.SuppressLint
import android.content.Context
import android.net.Uri
import android.os.Build
import androidx.tvprovider.media.tv.PreviewChannel
import androidx.tvprovider.media.tv.PreviewChannelHelper
import androidx.tvprovider.media.tv.PreviewProgram
import androidx.tvprovider.media.tv.TvContractCompat
import com.mukasanches.zapptv.R
import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo

@SuppressLint("RestrictedApi")
class HomeChannelPublisher(context: Context) {
    private val appContext = context.applicationContext
    private val prefs = appContext.getSharedPreferences("sanchestv-home-provider", Context.MODE_PRIVATE)

    fun publish(
        channels: List<Channel>,
        programs: Map<String, ProgramInfo>,
        favorites: Set<String>,
        recentIds: List<String>
    ) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O || channels.isEmpty()) return

        val selected = selectChannels(channels, favorites, recentIds)
        if (selected.isEmpty()) return

        val signature = selected.joinToString("|") { channel ->
            val program = programs[channel.id]
            listOf(
                channel.id,
                channel.name,
                channel.logoUri.orEmpty(),
                program?.title.orEmpty(),
                program?.nextTitle.orEmpty()
            ).joinToString(":")
        }.hashCode().toString()

        if (prefs.getString(KEY_SIGNATURE, null) == signature) return

        runCatching {
            val helper = PreviewChannelHelper(appContext)
            val existing = runCatching { helper.allChannels }
                .getOrDefault(emptyList())
                .firstOrNull { it.internalProviderId == INTERNAL_CHANNEL_ID }

            val appLink = Uri.parse("sanchestv://home")
            val logo = Uri.parse(
                "android.resource://${appContext.packageName}/${R.mipmap.ic_launcher}"
            )

            val builder = if (existing == null) {
                PreviewChannel.Builder()
            } else {
                PreviewChannel.Builder(existing)
            }

            val channel = builder
                .setInternalProviderId(INTERNAL_CHANNEL_ID)
                .setDisplayName("SANCHESTV • Minha TV")
                .setDescription("Favoritos e canais recentes")
                .setAppLinkIntentUri(appLink)
                .setLogo(logo)
                .build()

            val channelId = if (existing == null) {
                helper.publishChannel(channel)
            } else {
                helper.updatePreviewChannel(existing.id, channel)
                existing.id
            }

            val programsUri = TvContractCompat.buildPreviewProgramsUriForChannel(channelId)
            appContext.contentResolver.delete(programsUri, null, null)

            selected.forEachIndexed { index, source ->
                val epg = programs[source.id]
                val description = buildList {
                    epg?.title?.takeIf(String::isNotBlank)?.let(::add)
                    epg?.nextTitle?.takeIf(String::isNotBlank)?.let {
                        add("A seguir: $it")
                    }
                    source.category.takeIf(String::isNotBlank)?.let(::add)
                }.joinToString(" • ")

                val programBuilder = PreviewProgram.Builder()
                    .setChannelId(channelId)
                    .setType(TvContractCompat.PreviewPrograms.TYPE_CLIP)
                    .setTitle(source.name)
                    .setDescription(description.ifBlank { "Ao vivo" })
                    .setIntentUri(
                        Uri.parse("sanchestv://channel/${Uri.encode(source.id)}")
                    )
                    .setInternalProviderId(source.id)
                    .setWeight(selected.size - index)
                    .setPosterArtAspectRatio(
                        TvContractCompat.PreviewPrograms.ASPECT_RATIO_16_9
                    )

                source.logoUri
                    ?.takeIf(String::isNotBlank)
                    ?.let { runCatching { Uri.parse(it) }.getOrNull() }
                    ?.let(programBuilder::setPosterArtUri)

                helper.publishPreviewProgram(programBuilder.build())
            }

            prefs.edit()
                .putString(KEY_SIGNATURE, signature)
                .putLong(KEY_LAST_PUBLISH, System.currentTimeMillis())
                .apply()
        }
    }

    private fun selectChannels(
        channels: List<Channel>,
        favorites: Set<String>,
        recentIds: List<String>
    ): List<Channel> {
        val byId = channels.associateBy(Channel::id)
        val result = linkedMapOf<String, Channel>()

        favorites.forEach { id -> byId[id]?.let { result[id] = it } }
        recentIds.forEach { id -> byId[id]?.let { result[id] = it } }

        if (result.isEmpty()) {
            channels.take(FALLBACK_CHANNELS).forEach { result[it.id] = it }
        }

        return result.values.take(MAX_PROGRAMS)
    }

    companion object {
        private const val INTERNAL_CHANNEL_ID = "sanchestv-my-tv-v1"
        private const val KEY_SIGNATURE = "content_signature"
        private const val KEY_LAST_PUBLISH = "last_publish"
        private const val MAX_PROGRAMS = 20
        private const val FALLBACK_CHANNELS = 12
    }
}
